package com.aftersales.copilot.ticket.api;
import com.aftersales.copilot.auth.domain.AuthenticatedUser; import com.aftersales.copilot.common.api.ApiResponse; import com.aftersales.copilot.ticket.application.AfterSalesEligibilityService; import org.slf4j.MDC; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/customer/order-items") public class EligibilityController { private final AfterSalesEligibilityService service; public EligibilityController(AfterSalesEligibilityService service){this.service=service;} @GetMapping("/{id}/after-sales-eligibility") public ApiResponse<?> get(@AuthenticationPrincipal AuthenticatedUser user,@PathVariable long id){return ApiResponse.success(service.calculate(user,id),MDC.get("traceId"));} }
